// Inicializar la base de datos de nodos en el contexto global si no existe
let mapaNodos = global.get('pipea_nodos') || {};
let historialNodos = global.get('pipea_historial') || {};

// Extraer el ID del nodo desde el tópico (pipea/registro/ID)
let topicParts = msg.topic.split('/');
let nodoId = topicParts[2];

let payload = msg.payload;

// Si el payload está vacío o tiene estado offline (LWT o desconexión)
if (!payload || payload.estado === "offline") {
    if (mapaNodos[nodoId]) {
        // Pasar a historial de desconectados guardando sus últimas capacidades
        historialNodos[nodoId] = {
            ...mapaNodos[nodoId],
            ultimo_visto: new Date().toLocaleTimeString(),
            conectado: false
        };
        delete mapaNodos[nodoId];
    }
} else {
    // Nodo Online: Registrar o actualizar capacidades
    mapaNodos[nodoId] = {
        ...payload,
        ultimo_visto: new Date().toLocaleTimeString(),
        conectado: true
    };

    // Si existía en el historial, lo removemos de ahí porque volvió a conectarse
    if (historialNodos[nodoId]) {
        delete historialNodos[nodoId];
    }
}

// Guardar los cambios de vuelta en la memoria global de Node-RED
global.set('pipea_nodos', mapaNodos);
global.set('pipea_historial', historialNodos);

// Enviar los datos consolidados hacia la interfaz visual
msg.payload = {
    conectados: Object.values(mapaNodos),
    historial: Object.values(historialNodos)
};

return msg;

// Validar que el mensaje traiga datos válidos de la interfaz
if (!msg.payload || typeof msg.payload !== 'object') {
    return null; 
}

// Interceptamos el comando enviado según el msg.topic de la nueva interfaz
let comando = msg.topic;
let archivoSeleccionado = msg.payload.filename || "obra_pipea_default.json";

// Limpiamos el nombre del archivo por seguridad y asignamos la ruta relativa portátil
archivoSeleccionado = archivoSeleccionado.replace(/[^a-z0-9_\.]/gi, '_').toLowerCase();
msg.filename = `./${archivoSeleccionado}`;

// ==========================================
// CASO 1: ORDEN DE CARGAR ARCHIVO DESDE INTERFAZ
// ==========================================
if (comando === "read_file") {
    // Retornamos el msg listo con su filename modificado
    // Salida 2: Va hacia el nodo 'Leer JSON'
    return [null, msg];
}

// ==========================================
// CASO 2: ORDEN DE GUARDAR CONFIGURACIÓN EN DISCO
// ==========================================
if (comando === "save_file") {
    // Empaquetamos la estructura unificada limpia recibida de la UI
    msg.payload = {
        metadatos: {
            tipo_registro: "Puesta en Escena Unificada PIPEA",
            fecha_captura: new Date().toISOString()
        },
        fullObraData: msg.payload.dataToSave
    };

    // Salida 1: Envía el archivo directo al nodo 'Escribir JSON'
    return [msg, null];
}

// ==========================================
// CASO 3: ORDEN DE INYECTAR Y DESPLEGAR LA CONFIGURACIÓN A LA RED
// ==========================================
if (comando === "deploy_config") {
    // Si la interfaz ordenó un despliegue en caliente, no tocamos el disco duro.
    // Desviamos el payload compilado directamente hacia abajo.

    // NOTA OPERATIVA: Como en tu lienzo actual la Salida 2 va hacia 'Leer JSON',
    // necesitamos conectar un CABLE NUEVO desde la Salida 2 de este nodo 
    // directo a la entrada de 'Restaurar Memoria e Inundar Red'.
    return [null, msg];
}

return null;

// 1. Parsear el archivo .json que viene del disco duro de la computadora
let dataObra;
try {
    dataObra = JSON.parse(msg.payload);
} catch (e) {
    node.error("El archivo de escena está corrupto o vacío: " + e.toString());
    return null;
}

if (dataObra && dataObra.configuracion_nodos_capturados) {
    // 2. Restaurar la base de datos de memoria global con el JSON cargado
    global.set('pipea_nodos', dataObra.configuracion_nodos_capturados);

    let listaNodos = Object.values(dataObra.configuracion_nodos_capturados);
    let mensajesMqtt = [];

    // 3. Generar los mensajes MQTT para avisarle a los dispositivos físicos de sus nuevos valores
    listaNodos.forEach(nodo => {
        mensajesMqtt.push({
            topic: `pipea/config/${nodo.id}`,
            payload: {
                personaje_asignado: nodo.personaje_asignado,
                campos_actualizados: nodo.campos_configurables
            }
        });
    });

    // 4. Empaquetar un único mensaje consolidado para actualizar la UI sin saturar la red interna
    let mensajeUI = { 
        payload: { 
            conectados: listaNodos, 
            historial: Object.values(global.get('pipea_historial') || {}) 
        } 
    };

    // Salida 1 (Superior): Va a la plantilla visual y al debug para refrescar la pantalla
    // Salida 2 (Inferior): Va directo al broker Mosquitto para inundar la red
    return [ mensajeUI, mensajesMqtt ];
}
return null;

// 1. Inicializar o recuperar la estructura unificada desde el contexto global
let fullObraData = global.get("fullObraData") || {
    activeNodes: {}, // Estructura: { "id_nodo": { id, ip, rssi, status, lastSeen } }
    pieMatrix: [],   // Matriz de Cues / Pies teatrales
    archivoActivo: "obra_nueva.json"
};

// Obtener el tópico del mensaje para realizar el ruteo lógico
const topic = msg.topic || "";

// 2. CASO A: Procesar anuncio MQTT de nodo físico ("pipea/nodo/anuncio")
if (topic === "pipea/nodo/anuncio" || topic.endsWith("/anuncio")) {
    try {
        // Asegurar que el payload sea un objeto
        let anuncio = (typeof msg.payload === "string") ? JSON.parse(msg.payload) : msg.payload;

        // Validar que el anuncio contenga un identificador de nodo
        if (anuncio && anuncio.id) {
            const nodeId = anuncio.id;
            const tiempoActual = new Date().toLocaleTimeString();

            // Mapear y actualizar/crear el nodo en la jerarquía estricta
            fullObraData.activeNodes[nodeId] = {
                id: nodeId,
                ip: anuncio.ip || "0.0.0.0",
                rssi: anuncio.rssi || -100,
                status: anuncio.status || "online",
                lastSeen: tiempoActual
            };
        }
    } catch (e) {
        node.error("Error parseando anuncio MQTT: " + e.message, msg);
    }
}
// 3. CASO B: Procesar actualizaciones desde el UI-Template o carga de archivos
else if (msg.payload && msg.payload.fullObraData) {
    // Si viene directamente el objeto consolidado, hacemos un merge o reemplazo controlado
    if (msg.payload.fullObraData.activeNodes) {
        fullObraData.activeNodes = msg.payload.fullObraData.activeNodes;
    }
    if (msg.payload.fullObraData.pieMatrix) {
        fullObraData.pieMatrix = msg.payload.fullObraData.pieMatrix;
    }
    if (msg.payload.fullObraData.archivoActivo) {
        fullObraData.archivoActivo = msg.payload.fullObraData.archivoActivo;
    }
}

// 4. Limpieza higiénica de nodos desconectados (Opcional - TTL de 30 segundos)
// Si deseas un entorno reactivo estricto, puedes descomentar las siguientes líneas
/*
const AHORA = Date.now();
for (const id in fullObraData.activeNodes) {
    // Si el payload original incluyó una marca de tiempo Unix, puedes validar la vida del nodo aquí
}
*/

// 5. Salvar el estado actualizado en el contexto global de Node-RED
global.set("fullObraData", fullObraData);

// 6. Empaquetar la salida exactamente como la espera el HTML consolidado del Template
msg.payload = {
    fullObraData: fullObraData
};

return msg;

if (!msg.payload || typeof msg.payload !== 'object') {
    return null;
}

let comando = msg.topic;
let archivoSeleccionado = msg.payload.filename || 'obra_pipea_default.json';
archivoSeleccionado = archivoSeleccionado.replace(/[^a-z0-9.]/gi, '_').toLowerCase();
msg.filename = './' + archivoSeleccionado;

if (comando === 'read_file') {
    return [null, msg];
}

if (comando === 'save_file') {
    msg.payload = {
        metadatos: {
            tipo_registro: 'Puesta en Escena Unificada PIPEA',
            fecha_captura: new Date().toISOString()
        },
        fullObraData: msg.payload.dataToSave
    };
    return [msg, null];
}

if (comando === 'deploy_config') {
    return [null, msg];
}

return null;

if (msg.topic === 'deploy_config' && msg.payload) {
    let outputMsgs = [];
    let matrix = msg.payload.executionMatrix || [];

    matrix.forEach(row => {
        if (row.targetPersonaje) {
            let topic = pipea/config/${row.targetPersonaje.toLowerCase().trim()};
            outputMsgs.push({
                topic: topic,
                payload: {
                    triggerEvent: row.pieEvent,
                    actions: row.nodeActions
                }
            });
        }
    });

    return [outputMsgs];
}
return null;
